"use strict";(globalThis.webpackChunkgrc||=[]).push([[44112],{31228(e){e.exports=JSON.parse('[{"citeKey":"yildirim2025wisio","slug":"yildirim-2025-wisio-45f7","title":"WisIO: Automated I/O Bottleneck Detection with Multi-Perspective Views for HPC Workflows","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The 39th ACM International Conference on Supercomputing (ICS 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1145/3721145.3725742","abstract":"Modern HPC workloads involve large data transfers that can become bottlenecks. Existing analysis tools identify bottle- necks from per-file performance data but have limitations in parallelizability and rigid heuristic-based rules, necessitating an automated, efficient, and multi-perspective solution. We designed an automated tool, WisIO, that enables parallel and distributed analysis of multi-terabyte-scale workflow performance data. WisIO examines performance data from multiple perspectives, uses metric-driven bottleneck classifi- cation, and allows extensible mapping of bottlenecks to root causes. Experimental results demonstrate that WisIO\'s multi- perspective views substantially improve bottleneck coverage, showing an average increase of up to 805\xd7 when compared to analyzing performance data from a single perspective. In our performance evaluation, WisIO\'s metric-driven classification processed 340K bottlenecks per second, while its reasoning engine handled around 35K bottlenecks per sec- ond. In an analysis of five real-world HPC workloads, WisIO demonstrated up to 11\xd7 faster analysis time and identified up to 144x more bottlenecks compared to existing solutions.","hasAbstract":true,"lede":"Modern HPC workloads involve large data transfers that can become bottlenecks.","links":{"pdf":"https://grc.iit.edu/papers/2025/yildirim-2025-wisio-45f7.pdf"},"tags":["HPC","Workflows","I/O Analysis","I/O Bottleneck Detection","WisIO","LABIOS"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2024dftracer","slug":"devarajan-2024-dftracer-8fcb","title":"DFTracer: An Analysis-Friendly Data Flow Tracer for AI-Driven Workflows","authors":["H. Devarajan","L. Pottier","K. Velusamy","H. Zheng","I. Yildirim","O. Kogiou","W. Yu","A. Kougkas","X.-H. Sun","J.-S. Yeom","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'24)","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/sc41406.2024.00023","abstract":"Modern HPC workflows involve intricate coupling of simulation, data analytics, and artificial intelligence (AI) applications to improve time to scientific insight. These workflows require a cohesive set of performance analysis tools to provide a comprehensive understanding of data exchange patterns in HPC systems. However, current tools are not designed to work with an AI-based I/O software stack that requires tracing at multiple levels of the application. To this end, we developed a data flow tracer called DFTracer to capture data-centric events from workflows and the I/O stack to build a detailed understanding of the data exchange within AI-driven workflows. DFTracer has the following three novel features, including a unified interface to capture trace data from different layers in the software stack, a trace format that is analysis-friendly and optimized to support efficiently loading multi-million events in a few seconds, and the capability to tag events with workflow-specific context to perform domain-centric data flow analysis for workflows. Additionally, we demonstrate that DFTracer has a 1.44x smaller runtime overhead and 1.3-7.1x smaller trace size than state-of-the-art tracing tools such as Score-P, Recorder, and Darshan. Moreover, with AI-driven workflows, Score-P, Recorder, and Darshan cannot find I/O accesses from dynamically spawned processes, and their load performance of 100M events is three orders of magnitude slower than DFTracer. In conclusion, we demonstrate that DFTracer can capture multi-level performance data, including contextual event tagging with a low overhead of 1-5% from AI-driven workflows such as MuMMI and Microsoft\'s Megatron Deepspeed running on large-scale HPC systems. Index Terms-deep learning, workflows, I/O, tracer, multi- level, application apis, system calls, transparent, interception.","hasAbstract":true,"lede":"Modern HPC workflows involve intricate coupling of simulation, data analytics, and artificial intelligence (AI) applications to improve time to scientific insight.","links":{"pdf":"https://grc.iit.edu/papers/2024/devarajan-2024-dftracer-8fcb.pdf"},"tags":["Deep Learning","Workflows","I/O Tracing"],"_projectIds":["wisio"],"_funding":[{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true},{"agency":"NIH","award":"75N91019D00024","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2023exploringimpacts","slug":"yildirim-2023-exploring-impacts-090b","title":"Exploring the Impacts of Multiple I/O Metrics in Identifying I/O Bottlenecks","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'23), November 12-17, 2023","type":"Technical Report","entryType":"misc","date":"November, 2023","year":2023,"era":"iit","month":11,"hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2023/yildirim-2023-exploring-impacts-090b-poster.pdf"},"tags":["I/O Analysis","I/O Metrics","I/O Bottleneck Detection","WisIO"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2023iomax","slug":"yildirim-2023-iomax-3919","title":"IOMax: Maximizing Out-of-Core I/O Analysis Performance on HPC Systems","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Parallel Data Systems Workshop (PDSW\'23)","type":"Workshop","entryType":"inproceedings","date":"November, 2023","year":2023,"era":"iit","month":11,"doi":"10.1145/3624062.3624191","abstract":"I/O analysis is an essential task for improving the performance of scientific applications on high-performance computing (HPC) systems. However, current analysis tools, which often use data drilling techniques (iterative exploration for deeper insights), treat every query independently and do not optimize column data for data-slicing (extracting specific data subsets), resulting in subpar querying performance. In this paper, we designed IOMax, a tool for efficient data drilling analysis on large-scale I/O traces. IOMax utilizes a novel query optimization technique to improve the query performance by 8.6x while reducing the memory footprint required for analysis by 11x. Additionally, it employs data transformation techniques to improve data-slicing performance by up to 11.4x. In conclusion, IOMax optimizes I/O analysis for scientific workflows on the Lassen supercomputer, resulting in up to 7x improvement.","hasAbstract":true,"lede":"We designed IOMax, a tool for efficient data drilling analysis on large-scale I/O traces.","links":{"pdf":"https://grc.iit.edu/papers/2023/yildirim-2023-iomax-3919.pdf"},"tags":["I/O Analysis","Out-of-Core Analysis","Data Drilling","WisIO"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2022multifacetedapproach","slug":"yildirim-2022-multifaceted-approach-da2d","title":"A Multifaceted Approach to Automated I/O Bottleneck Detection for HPC Workloads","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'22)","type":"Poster","entryType":"misc","date":"November, 2022","year":2022,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2022/yildirim-2022-multifaceted-approach-da2d.pdf","poster":"https://grc.iit.edu/papers/2022/yildirim-2022-multifaceted-approach-da2d-poster.pdf"},"tags":["I/O Characterization","I/O Bottleneck Detection","WisIO"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);